           const newLat =
            secondPoint.lat - latStep * (steps - progress);
           const newLng =
            secondPoint.lng - lngStep * (steps - progress);
           const newLatLng = L.latLng(newLat, newLng);

           marker.setLatLng(newLatLng); // Update the marker's position

