      "source": [
        "def write_vocab_file(filepath, vocab):\n",
        "  with open(filepath, 'w') as f:\n",
        "    for token in vocab:\n",
        "      print(token, file=f)\n",
        "write_vocab_file('en_vocab.txt', en_vocab)\n",
        "write_vocab_file('fr_vocab.txt', fr_vocab)"
      ]
