simplify my code:
 public async Task<Jobs> ObtainWorkflowAssignmentsForTargetLanguage(string token, long projectId, string lang)
 {
     var response = await GetRequestWithToken($"{apiURL}/projects/{projectId}/workflow/assignment?targetLanguages={lang}", token);
     Jobs jobs = JsonSerializer.Deserialize<Jobs>(response);
     if (jobs.jobs.Length < 100)
     {
         return jobs;
     }
     else
     {
         int i = 2;
         response = await GetRequestWithToken($"{apiURL}/projects/{projectId}/workflow/assignment?targetLanguages={lang}&page={i}", token);
         Jobs jobs2 = JsonSerializer.Deserialize<Jobs>(response);
         Jobs jobsConcatenated = new()
         {
             jobs = new Job[jobs.jobs.Length + jobs2.jobs.Length]
         };
         Array.Copy(jobs.jobs, 0, jobsConcatenated.jobs, 0, jobs.jobs.Length);
         Array.Copy(jobs2.jobs, 0, jobsConcatenated.jobs, jobs.jobs.Length, jobs2.jobs.Length);
         while (jobs2.jobs.Length == 100)
         {
             i++;
             response = await GetRequestWithToken($"{apiURL}/projects/{projectId}/workflow/assignment?targetLanguages={lang}&page={i}", token);
             jobs2 = JsonSerializer.Deserialize<Jobs>(response);
             Jobs jobsConcatenated2 = new()
             {
                 jobs = new Job[jobsConcatenated.jobs.Length + jobs2.jobs.Length]
             };
             Array.Copy(jobsConcatenated.jobs, 0, jobsConcatenated2.jobs, 0, jobsConcatenated.jobs.Length);
             Array.Copy(jobs2.jobs, 0, jobsConcatenated2.jobs, jobsConcatenated.jobs.Length, jobs2.jobs.Length);
             jobsConcatenated = jobsConcatenated2;
         }
         return jobsConcatenated;
     }
 }

