        FillRect(dc,&rcArea,hBr);
        DeleteObject(hBr);
       }    

      if(wParam==ODR_BACKCOL)
       {
        dc=((LPDRAWITEMSTRUCT)lParam)->hDC;
        ColVal=Fnt->GetCol(BACKCOL);
        GetClientRect(hDlg, &rcArea);
