                    function setupGame() {
                        const gameboard = document.getElementById('gameboard');
                        gameboard.innerHTML = '';

                        const prizeCard = Math.floor(Math.random() * 9) + 1;

                        for (let i = 1; i <= 9; i++) {
                            const card = document.createElement('div');
                            const img = document.createElement('img');

                            img.src = 'media/лапка.jpg';
                            img.style.width = '100px';
                            img.style.height = '100px';

                            card.className = 'card';
                            card.id = 'card-' + i;

                            if (i === prizeCard) {
                                card.dataset.prize = true;
                            }

                            card.appendChild(img);
                            card.onclick = function() { revealPrize(card); };
                            gameboard.appendChild(card);
                        }
                    }

                    function revealPrize(card) {
                        const img = card.querySelector('img');
                        if (card.dataset.prize) {
                            img.src = 'media/зеленая лапа.jpg';
