                        } else {
                            img.src = 'media/красная лапа.jpg';
                            alert('К сожалению, вам не повезло...');
                        }
                        disableCards();
                    }

                    function disableCards() {
                        const cards = document.querySelectorAll('.card');
                        cards.forEach(card => {
                            card.onclick = null;
                        });
                    }

                    setupGame();
